/* css/home.css */
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #070b14; color: #fff;
  font-family: "SamsungOneArabic", "Samsung One Arabic", "TizenSans", "Noto Sans Arabic", "Noto Kufi Arabic", Tahoma, Arial, sans-serif;
  -webkit-font-smoothing: antialiased; }
* { box-sizing: border-box; }
#app { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; -webkit-transform-origin: 0 0; transform-origin: 0 0; }
/* living picture: clouds drift behind the pyramids, the Nile ripples and sparkles,
   the felucca rocks on the water and a few birds cross the sky now and then */
.scene { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; background: #0b1424;
  -webkit-animation: kb 50s ease-in-out infinite alternate; animation: kb 50s ease-in-out infinite alternate; will-change: transform; }
.scene .full { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
.sun { position: absolute; left: 1500px; top: 160px; width: 760px; height: 760px; border-radius: 50%;
  background: -webkit-radial-gradient(center, circle, rgba(255,238,196,0.75) 0%, rgba(255,230,180,0.25) 35%, rgba(255,230,180,0) 70%);
  background: radial-gradient(circle at center, rgba(255,238,196,0.75) 0%, rgba(255,230,180,0.25) 35%, rgba(255,230,180,0) 70%);
  -webkit-animation: glow 9s ease-in-out infinite alternate; animation: glow 9s ease-in-out infinite alternate; }
.sky-clouds { position: absolute; left: 0; top: 0; width: 3840px; height: 560px; background: url(images/nile-clouds.webp) repeat-x; background-size: 1920px 560px;
  -webkit-animation: drift 90s linear infinite; animation: drift 90s linear infinite; will-change: transform; }
.water, .glints { position: absolute; left: 0; top: 640px; width: 1920px; height: 440px; background-repeat: no-repeat; background-size: 1920px 440px; }
.water { background-image: url(images/nile-water.webp); opacity: 0.6;
  -webkit-animation: ripple 4.5s ease-in-out infinite alternate; animation: ripple 4.5s ease-in-out infinite alternate; will-change: transform; }
.glints { width: 1980px; left: -30px; }
.glints.g1 { background-image: url(images/nile-glints1.webp); -webkit-animation: twinkle 3.2s ease-in-out infinite, gdrift 16s ease-in-out infinite alternate; animation: twinkle 3.2s ease-in-out infinite, gdrift 16s ease-in-out infinite alternate; }
.glints.g2 { background-image: url(images/nile-glints2.webp); -webkit-animation: twinkle 3.2s ease-in-out -1.6s infinite, gdrift 21s ease-in-out infinite alternate-reverse; animation: twinkle 3.2s ease-in-out -1.6s infinite, gdrift 21s ease-in-out infinite alternate-reverse; }
.boat { position: absolute; left: 1530px; top: 525px; width: 115px; height: 187px; -webkit-transform-origin: 55% 92%; transform-origin: 55% 92%;
  -webkit-animation: bob 5s ease-in-out infinite alternate; animation: bob 5s ease-in-out infinite alternate; will-change: transform; }
.birds { position: absolute; left: 0; top: 300px; width: 180px; height: 70px; -webkit-animation: fly 60s linear infinite; animation: fly 60s linear infinite; }
.birds path { fill: none; stroke: #2b2722; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round;
  -webkit-transform-box: fill-box; transform-box: fill-box; -webkit-transform-origin: 50% 100%; transform-origin: 50% 100%;
  -webkit-animation: flap .55s ease-in-out infinite alternate; animation: flap .55s ease-in-out infinite alternate; }
.birds path:nth-child(2) { -webkit-animation-delay: -.2s; animation-delay: -.2s; }
.birds path:nth-child(3) { -webkit-animation-delay: -.35s; animation-delay: -.35s; }
.birds path:nth-child(4) { -webkit-animation-delay: -.1s; animation-delay: -.1s; }
@-webkit-keyframes kb { from { -webkit-transform: scale(1); } to { -webkit-transform: scale(1.06) translate3d(-18px,-6px,0); } }
@keyframes kb { from { transform: scale(1); } to { transform: scale(1.06) translate3d(-18px,-6px,0); } }
@-webkit-keyframes glow { from { opacity: 0.55; } to { opacity: 1; } }
@keyframes glow { from { opacity: 0.55; } to { opacity: 1; } }
@-webkit-keyframes drift { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(-1920px,0,0); } }
@keyframes drift { from { transform: translate3d(0,0,0); } to { transform: translate3d(-1920px,0,0); } }
@-webkit-keyframes ripple { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(7px,2px,0); } }
@keyframes ripple { from { transform: translate3d(0,0,0); } to { transform: translate3d(7px,2px,0); } }
@-webkit-keyframes twinkle { 0%, 100% { opacity: 0.15; } 50% { opacity: 0.95; } }
@keyframes twinkle { 0%, 100% { opacity: 0.15; } 50% { opacity: 0.95; } }
@-webkit-keyframes gdrift { from { -webkit-transform: translate3d(0,0,0); } to { -webkit-transform: translate3d(30px,0,0); } }
@keyframes gdrift { from { transform: translate3d(0,0,0); } to { transform: translate3d(30px,0,0); } }
@-webkit-keyframes bob { from { -webkit-transform: rotate(-1.3deg) translate3d(0,0,0); } to { -webkit-transform: rotate(1.5deg) translate3d(0,2px,0); } }
@keyframes bob { from { transform: rotate(-1.3deg) translate3d(0,0,0); } to { transform: rotate(1.5deg) translate3d(0,2px,0); } }
/* birds fly from right to left in 36 s, then the sky stays empty for the rest of the minute */
@-webkit-keyframes fly { 0% { -webkit-transform: translate3d(2050px,0,0); } 30% { -webkit-transform: translate3d(1250px,-30px,0); } 60% { -webkit-transform: translate3d(-260px,10px,0); } 100% { -webkit-transform: translate3d(-260px,10px,0); } }
@keyframes fly { 0% { transform: translate3d(2050px,0,0); } 30% { transform: translate3d(1250px,-30px,0); } 60% { transform: translate3d(-260px,10px,0); } 100% { transform: translate3d(-260px,10px,0); } }
@-webkit-keyframes flap { from { -webkit-transform: scaleY(1); } to { -webkit-transform: scaleY(0.3); } }
@keyframes flap { from { transform: scaleY(1); } to { transform: scaleY(0.3); } }
#stagebg { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; -webkit-transform-origin: 0 0; transform-origin: 0 0; }
.shade { position: absolute; left: 0; top: 0; right: 0; bottom: 0;
  background: -webkit-linear-gradient(top, rgba(4,8,18,0.6) 0%, rgba(4,8,18,0.1) 24%, rgba(4,8,18,0) 45%, rgba(4,8,18,0.55) 70%, rgba(4,8,18,0.92) 100%);
  background: linear-gradient(to bottom, rgba(4,8,18,0.6) 0%, rgba(4,8,18,0.1) 24%, rgba(4,8,18,0) 45%, rgba(4,8,18,0.55) 70%, rgba(4,8,18,0.92) 100%); }
.shadow { text-shadow: 0 3px 16px rgba(0,0,0,0.6), 0 1px 3px rgba(0,0,0,0.5); }


/* ---------- background choices: Nile (moving), Nile (still), plain night ---------- */
.night { position: absolute; left: 0; top: 0; right: 0; bottom: 0; display: none;
  background: radial-gradient(ellipse at 75% 20%, #1b2a4a 0%, #0c1426 45%, #05080f 100%); }
.bg-dark #stagebg { display: none; }
.bg-dark .night { display: block; }
.bg-still .scene, .bg-still .scene * { -webkit-animation: none !important; animation: none !important; }
.bg-still .birds { display: none; }

/* ---------- clock, name, dates (top right) ---------- */
.hero { position: absolute; right: 80px; top: 56px; }
.time { display: -webkit-flex; display: flex; -webkit-align-items: flex-end; align-items: flex-end; }
.clock { font-size: 132px; font-weight: 800; line-height: 0.95; letter-spacing: -2px; }
.ampm { font-size: 36px; font-weight: 700; color: #ffd27a; margin: 0 16px 14px 0; }
/* the name, with a soft light passing over it now and then */
.by { display: inline-block; margin-top: 10px; font-size: 24px; font-weight: 700; letter-spacing: 0.5px; text-shadow: none;
  background: linear-gradient(105deg, #f0b847 0%, #ffd27a 38%, #fffbe9 48%, #ffffff 50%, #fffbe9 52%, #ffd27a 62%, #f0b847 100%);
  background-size: 300% 100%; -webkit-background-clip: text; background-clip: text; color: transparent;
  -webkit-filter: drop-shadow(0 2px 6px rgba(0,0,0,0.55)); filter: drop-shadow(0 2px 6px rgba(0,0,0,0.55));
  -webkit-animation: shine 4.5s ease-in-out infinite; animation: shine 4.5s ease-in-out infinite; }
@-webkit-keyframes shine { 0% { background-position: 100% 0; } 55% { background-position: 0% 0; } 100% { background-position: 0% 0; } }
@keyframes shine { 0% { background-position: 100% 0; } 55% { background-position: 0% 0; } 100% { background-position: 0% 0; } }
.date { font-size: 32px; font-weight: 700; margin-top: 10px; }
.hijri { font-size: 28px; font-weight: 700; margin-top: 6px; color: #ffd27a; }

/* ---------- weather (top left) ---------- */
.glass { background: rgba(8,12,22,0.62); border: 2px solid rgba(255,255,255,0.13); box-shadow: 0 24px 60px rgba(0,0,0,0.38); }
.wx { position: absolute; left: 80px; top: 70px; height: 96px; padding: 0 30px 0 26px; border-radius: 28px;
  display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; font-size: 26px; color: #e3e8f1; }
.wx:empty { display: none; }
.wx svg { width: 58px; height: 58px; margin-left: 16px; }
.wx b { font-size: 46px; font-weight: 800; color: #fff; margin-left: 16px; }
.no-wx .wx { display: none; }

/* ---------- the row of app buttons ---------- */
.dockrow { position: absolute; left: 0; right: 0; bottom: 92px; }
.no-news .dockrow { bottom: 34px; }
.hint { display: inline-block; margin-right: 80px; padding: 7px 20px; border-radius: 14px; background: rgba(8,12,22,0.55);
  font-size: 21px; color: rgba(255,255,255,0.7); }
.hint b { color: rgba(255,255,255,0.85); }
.rowview { position: relative; overflow: hidden; padding: 34px 80px 26px; }
.row { display: -webkit-flex; display: flex; -webkit-transition: -webkit-transform .28s ease; transition: transform .28s ease; }
.size-l { --tw: 264px; --th: 218px; --gap: 38px; --nf: 26px; }
.size-m { --tw: 222px; --th: 184px; --gap: 32px; --nf: 24px; }
.size-s { --tw: 184px; --th: 152px; --gap: 26px; --nf: 22px; }
.tile { -webkit-flex: 0 0 auto; flex: 0 0 auto; width: var(--tw); margin-left: var(--gap); position: relative; }
.frame { width: var(--tw); height: var(--th); border-radius: 26px; overflow: hidden; position: relative;
  background: rgba(8,12,22,0.62); border: 3px solid rgba(255,255,255,0.14); box-shadow: 0 18px 44px rgba(0,0,0,0.42);
  -webkit-transition: -webkit-transform .18s ease, border-color .18s, box-shadow .18s; transition: transform .18s ease, border-color .18s, box-shadow .18s; }
.frame img { position: absolute; left: 0; top: 0; width: 100%; height: 100%; object-fit: cover; display: block; }
.frame .ph { position: absolute; left: 0; top: 0; right: 0; bottom: 0; display: -webkit-flex; display: flex;
  -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center;
  font-size: calc(var(--th) * 0.36); font-weight: 800; color: rgba(255,255,255,0.92); }
.frame .glyph { position: absolute; left: 0; top: 0; right: 0; bottom: 0; display: -webkit-flex; display: flex;
  -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.frame .glyph svg { width: 44%; height: 44%; fill: #ffd27a; }
.tile .name { margin-top: 14px; font-size: var(--nf); font-weight: 700; text-align: center; white-space: nowrap; overflow: hidden;
  text-overflow: ellipsis; color: rgba(255,255,255,0.8); text-shadow: 0 2px 10px rgba(0,0,0,0.8);
  -webkit-transition: -webkit-transform .18s; transition: transform .18s; }
.tile.focus .frame, .app.focus .frame { -webkit-transform: scale(1.1); transform: scale(1.1); border-color: #ffb020;
  box-shadow: 0 0 0 5px rgba(255,176,32,0.35), 0 26px 56px rgba(0,0,0,0.55); }
.tile.focus .name, .app.focus .name { color: #fff; font-weight: 800; -webkit-transform: translateY(10px); transform: translateY(10px); }
/* a button being moved: lifted, blue, with arrows on both sides */
.tile.moving .frame { -webkit-transform: scale(1.12) translateY(-16px); transform: scale(1.12) translateY(-16px); border-color: #5ab0ff;
  box-shadow: 0 0 0 6px rgba(90,176,255,0.4), 0 34px 60px rgba(0,0,0,0.6); }
.tile .arr { display: none; position: absolute; top: calc(var(--th) / 2 - 40px); width: 34px; height: 60px; border-radius: 12px; background: #5ab0ff; color: #04101f;
  font-size: 26px; font-weight: 800; line-height: 60px; text-align: center; z-index: 2; }
.tile .arr.r { right: -30px; } .tile .arr.l { left: -30px; }
.tile.moving .arr { display: block; }
.tile.moving .name { color: #9fd0ff; -webkit-transform: translateY(10px); transform: translateY(10px); }

/* ---------- sports news ticker ---------- */
.ticker { position: absolute; left: 80px; right: 80px; bottom: 26px; height: 72px; display: -webkit-flex; display: flex;
  -webkit-align-items: center; align-items: center; overflow: hidden; border-radius: 22px; }
.no-news .ticker { display: none; }
.tlabel { -webkit-flex-shrink: 0; flex-shrink: 0; height: 100%; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center;
  padding: 0 24px; font-size: 25px; font-weight: 800; color: #1b1200; background: linear-gradient(135deg, #ffb020, #ff7a3d); }
.tlabel svg { width: 34px; height: 34px; margin-left: 10px; }
.tview { -webkit-flex: 1; flex: 1; height: 100%; position: relative; overflow: hidden;
  -webkit-mask-image: linear-gradient(to right, transparent 0, #000 60px, #000 calc(100% - 60px), transparent 100%);
  mask-image: linear-gradient(to right, transparent 0, #000 60px, #000 calc(100% - 60px), transparent 100%); }
.ttrack { position: absolute; left: 0; top: 0; height: 100%; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center;
  white-space: nowrap; direction: rtl; will-change: transform; }
.ttrack .it { font-size: 28px; font-weight: 700; }
.ttrack .src { font-size: 21px; color: #9aa6ba; font-weight: 600; margin-right: 12px; }
.ttrack .dot { display: inline-block; width: 10px; height: 10px; margin: 0 26px; -webkit-transform: rotate(45deg); transform: rotate(45deg); background: #ffb020; border-radius: 2px; }
.tmsg { position: absolute; right: 24px; top: 0; height: 100%; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; font-size: 24px; color: #9aa6ba; }

/* ---------- all apps ---------- */
.drawer { position: absolute; left: 0; top: 0; right: 0; bottom: 0; background: #060a14; display: none;
  -webkit-flex-direction: column; flex-direction: column; padding: 56px 0 0; }
.drawer.open { display: -webkit-flex; display: flex; }
.dhead { padding: 0 80px; -webkit-flex-shrink: 0; flex-shrink: 0; }
.dhead h2 { margin: 0; font-size: 48px; font-weight: 800; }
.dhead h2 small { font-size: 26px; color: #9aa6ba; font-weight: 700; margin-right: 12px; }
.dhead p { margin: 10px 0 0; font-size: 23px; color: #9aa6ba; }
.dhead p b { color: #e3e8f1; }
.star { color: #ffd27a; }
.gridview { -webkit-flex: 1; flex: 1; position: relative; overflow: hidden; }
.grid { position: absolute; left: 80px; right: 80px; top: 0; display: -webkit-flex; display: flex; -webkit-flex-wrap: wrap; flex-wrap: wrap;
  padding: 34px 0 60px; -webkit-transition: -webkit-transform .25s ease; transition: transform .25s ease; }
.app { width: 14.2857%; height: 262px; display: -webkit-flex; display: flex; -webkit-flex-direction: column; flex-direction: column;
  -webkit-align-items: center; align-items: center; position: relative; --tw: 196px; --th: 162px; --nf: 22px; }
.app .frame { border-radius: 24px; }
.app .name { margin-top: 14px; width: 210px; font-size: 22px; font-weight: 700; text-align: center; white-space: nowrap; overflow: hidden;
  text-overflow: ellipsis; color: rgba(255,255,255,0.8); -webkit-transition: -webkit-transform .18s; transition: transform .18s; }
.app .badge { position: absolute; top: -8px; left: 20px; width: 44px; height: 44px; border-radius: 50%; background: #ffb020; color: #1b1200;
  font-size: 26px; line-height: 44px; text-align: center; z-index: 2; box-shadow: 0 6px 16px rgba(0,0,0,0.5); display: none; }
.app.fav .badge { display: block; }
.dempty { padding: 60px 80px; font-size: 30px; color: #9aa6ba; }

/* ---------- menus and questions ---------- */
.modal { position: absolute; left: 0; top: 0; right: 0; bottom: 0; background: rgba(2,4,10,0.6); display: none;
  -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.modal.open { display: -webkit-flex; display: flex; }
.panel { width: 900px; max-height: 900px; display: -webkit-flex; display: flex; -webkit-flex-direction: column; flex-direction: column;
  background: rgba(10,15,28,0.97); border: 2px solid rgba(255,255,255,0.14); border-radius: 34px; box-shadow: 0 40px 90px rgba(0,0,0,0.6); padding: 34px 34px 28px; }
.panel h3 { margin: 0 8px 8px; font-size: 38px; font-weight: 800; }
.panel .ptext { margin: 4px 8px 14px; font-size: 25px; color: #c9d1de; white-space: pre-line; line-height: 1.5; }
.plist { overflow: hidden; position: relative; margin-top: 10px; }
.pitem { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; min-height: 78px; padding: 10px 24px; border-radius: 18px;
  font-size: 28px; font-weight: 700; color: #e3e8f1; }
.pitem + .pitem { margin-top: 6px; }
.pitem .pl { -webkit-flex: 1; flex: 1; min-width: 0; }
.pitem .ps { display: block; font-size: 20px; font-weight: 600; color: #9aa6ba; margin-top: 2px; }
.pitem .pv { -webkit-flex-shrink: 0; flex-shrink: 0; margin-right: 20px; font-size: 26px; color: #ffd27a; direction: rtl; }
.pitem .pv i { font-style: normal; opacity: 0.6; margin: 0 10px; }
.pitem.danger { color: #ff8a8d; }
.pitem.focus { background: #ffb020; color: #1b1200; }
.pitem.focus .ps { color: rgba(27,18,0,0.7); }
.pitem.focus .pv { color: #1b1200; }
.pbtns { display: -webkit-flex; display: flex; margin-top: 18px; }
.pbtns .pitem { -webkit-flex: 1; flex: 1; -webkit-justify-content: center; justify-content: center; margin: 0 6px; background: rgba(255,255,255,0.08); }
.pbtns .pitem + .pitem { margin-top: 0; }
.pbtns .pitem.focus { background: #ffb020; }
.pbtns .pitem.danger.focus { background: #e5484d; color: #fff; }

.loading { position: absolute; left: 0; top: 0; right: 0; bottom: 0; background: rgba(2,4,10,0.55); display: none;
  -webkit-flex-direction: column; flex-direction: column; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; font-size: 30px; font-weight: 700; }
.loading.open { display: -webkit-flex; display: flex; }
.loading i { width: 80px; height: 80px; border-radius: 50%; border: 8px solid rgba(255,255,255,0.18); border-top-color: #ffb020; margin-bottom: 24px;
  -webkit-animation: spin 0.9s linear infinite; animation: spin 0.9s linear infinite; }
@-webkit-keyframes spin { to { -webkit-transform: rotate(360deg); } }
@keyframes spin { to { transform: rotate(360deg); } }

#toast { position: absolute; left: 50%; bottom: 430px; -webkit-transform: translateX(-50%); transform: translateX(-50%);
  padding: 16px 34px; border-radius: 18px; background: rgba(8,12,22,0.92); border: 2px solid rgba(255,255,255,0.14); color: #fff; font-size: 28px; font-weight: 700;
  white-space: nowrap; opacity: 0; -webkit-transition: opacity .3s; transition: opacity .3s; pointer-events: none; z-index: 20; }
#toast.show { opacity: 1; }
.in-drawer #toast { bottom: 46px; }

