})();

/* ==========================================================================
   ui.js — small building blocks for the remote: a list menu, a question
   with buttons, a message at the bottom and a "please wait" spinner.
   (The same calls the updater js/ota.js uses in the IPTV app.)
   ========================================================================== */
var UI = (function () {
  var cur = null;          /* the open menu / question: { onKey } */
  var toastTimer = null;

  function $(id) { return document.getElementById(id); }
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }

  function open(html) {
    var m = $('modal');
    m.innerHTML = html;
    m.className = 'modal open';
    $('toast').className = '';
  }
  function close() {
    cur = null;
    var m = $('modal');
    m.className = 'modal';
    m.innerHTML = '';
  }

  /* a list: opt = { title, text, items: [{label, value, sub, val, danger}], index,
     onSelect(value, item), onSide(item, dir, index) for items with side: true, onBack } */
  function menu(opt) {
    var items = opt.items || [], idx = Math.max(0, Math.min(items.length - 1, opt.index || 0));
    var h = '<div class="panel"><h3>' + esc(opt.title || '') + '</h3>' + (opt.text ? '<div class="ptext">' + esc(opt.text) + '</div>' : '') + '<div class="plist" id="plist">';
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      h += '<div class="pitem' + (it.danger ? ' danger' : '') + '" data-i="' + i + '"><span class="pl">' + esc(it.label) +
        (it.sub ? '<span class="ps">' + esc(it.sub) + '</span>' : '') + '</span>' +
        (it.val != null ? '<span class="pv">' + (it.side ? '<i>‹</i>' : '') + esc(it.val) + (it.side ? '<i>›</i>' : '') + '</span>' : '') + '</div>';
    }
    open(h + '</div></div>');
    var list = $('plist'), rows = list.children;
    list.style.maxHeight = (900 - 34 - 28 - 60 - (opt.text ? 120 : 0)) + 'px';
    function paint() {
      for (var j = 0; j < rows.length; j++) rows[j].className = rows[j].className.replace(/ ?focus/g, '') + (j === idx ? ' focus' : '');
      var r = rows[idx];
      if (r) {
        if (r.offsetTop < list.scrollTop) list.scrollTop = r.offsetTop;
        else if (r.offsetTop + r.offsetHeight > list.scrollTop + list.clientHeight) list.scrollTop = r.offsetTop + r.offsetHeight - list.clientHeight;
      }
    }
    paint();
    cur = {
      onKey: function (k) {
        if (k === 'up') { if (idx > 0) { idx--; paint(); } }
        else if (k === 'down') { if (idx < items.length - 1) { idx++; paint(); } }
        else if ((k === 'left' || k === 'right') && items[idx] && items[idx].side && opt.onSide) {
          opt.onSide(items[idx], k === 'left' ? 1 : -1, idx);
        }
        else if (k === 'enter') {
          var it2 = items[idx];
          if (it2 && it2.side && opt.onSide) { opt.onSide(it2, 1, idx); return; }
          close();
          if (opt.onSelect && it2) opt.onSelect(it2.value, it2);
        }
        else if (k === 'back') { close(); if (opt.onBack) opt.onBack(); }
      }
    };
  }

  /* a question with buttons side by side: opt = { title, text, buttons: [{label, value, danger}], index, onSelect(value) } */
  function confirm(opt) {
    var b = opt.buttons || [{ label: 'تمام', value: 'ok' }], idx = opt.index || 0;
    var h = '<div class="panel"><h3>' + esc(opt.title || '') + '</h3>' + (opt.text ? '<div class="ptext">' + esc(opt.text) + '</div>' : '') + '<div class="pbtns" id="pbtns">';
    for (var i = 0; i < b.length; i++) h += '<div class="pitem' + (b[i].danger ? ' danger' : '') + '">' + esc(b[i].label) + '</div>';
    open(h + '</div></div>');
    var rows = $('pbtns').children;
    function paint() { for (var j = 0; j < rows.length; j++) rows[j].className = rows[j].className.replace(/ ?focus/g, '') + (j === idx ? ' focus' : ''); }
    paint();
    cur = {
      onKey: function (k) {
        /* right to left: the first button is on the right */
        if (k === 'left') { if (idx < b.length - 1) { idx++; paint(); } }
        else if (k === 'right') { if (idx > 0) { idx--; paint(); } }
        else if (k === 'enter') { close(); if (opt.onSelect) opt.onSelect(b[idx].value); }
        else if (k === 'back') { close(); if (opt.onSelect) opt.onSelect(null); }
      }
    };
  }

  function toast(text, ms) {
    var t = $('toast');
    t.innerHTML = esc(text);
    t.className = 'show';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.className = ''; }, ms || 3000);
  }

  var busy = false;
  function loading(on, text) {
    busy = !!on;
    $('loadingText').innerHTML = esc(text || '');
    $('loading').className = 'loading' + (on ? ' open' : '');
  }

  return {
    menu: menu, confirm: confirm, toast: toast, loading: loading, close: close, esc: esc,
    modal: function () { return busy ? { onKey: function () {} } : cur; }
  };
})();

/* ==========================================================================
   ota.js — updates the app over the internet, no laptop needed.
   The app's own code (page, styles, screens) is downloaded from
   https://mabdullah-apps.github.io/iptv/<platform>/ and kept on the device;
   boot.js starts that newer code the next time the app opens.
   Never part of an update: js/config.js (the private built-in account),
   the saved subscriptions, favourites and settings - those stay on the device.
   ========================================================================== */
var OTA = (function () {
  var BOOT = window.OTA_BOOT || { app: 'iptv', platform: 'tizen', shell: 1, base: '0', running: '0', from: 'package', notes: [] };
  var cfg = window.IPTV_CONFIG || window.RADIO_TEST || {};   /* tests only */
  var BASE_URL = (cfg.otaUrl || 'https://mabdullah-apps.github.io/' + (BOOT.app || 'iptv') + '/') + BOOT.platform + '/';
  var FIRST_CHECK = cfg.otaFirstCheck || 45 * 1000;      /* after the app opens */
  var EVERY = 6 * 3600 * 1000;                            /* then every 6 hours */

  var st = { status: 'idle', latest: null, error: '', checkedAt: 0, busy: false };

  function cmp(a, b) {
    var x = String(a || '0').split('.'), y = String(b || '0').split('.');
    for (var i = 0; i < Math.max(x.length, y.length); i++) {
      var d = (parseInt(x[i], 10) || 0) - (parseInt(y[i], 10) || 0);
      if (d) return d > 0 ? 1 : -1;
    }
    return 0;
  }
  function ls(k, v) {
    try {
      if (v === undefined) return localStorage.getItem(k);
      if (v === null) localStorage.removeItem(k); else localStorage.setItem(k, v);
    } catch (e) {}
    return null;
  }
  function now() { return new Date().getTime(); }

  /* FNV-1a over the text, the same sum the publishing script writes */
  function sum(s) {
    var h = 0x811c9dc5;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
    }
    return ('0000000' + h.toString(16)).slice(-8);
  }

  function get(url, cb) {
    var x = new XMLHttpRequest(), done = false;
    function end(err, txt) { if (done) return; done = true; cb(err, txt); }
    try {
      x.open('GET', url + (url.indexOf('?') < 0 ? '?' : '&') + 't=' + now(), true);
      x.timeout = 30000;
      x.onload = function () { if (x.status >= 200 && x.status < 300) end(null, x.responseText); else end('http ' + x.status); };
      x.onerror = function () { end('network'); };
      x.ontimeout = function () { end('timeout'); };
      x.send();
    } catch (e) { end('network'); }
  }

  /* the version that is downloaded and will start next time (if newer than the running one) */
  function ready() {
    var v = ls('ota.ready');
    return v && cmp(v, BOOT.running) > 0 && v !== ls('ota.bad') ? v : '';
  }

  function auto() { return ls('ota.auto') !== 'off'; }
  function setAuto(on) { ls('ota.auto', on ? null : 'off'); }

  /* cb({ status: 'latest' | 'ready' | 'needShell' | 'error', version, notes, fresh }) */
  function check(cb) {
    cb = cb || function () {};
    if (st.busy) { cb({ status: 'busy' }); return; }
    st.busy = true;
    get(BASE_URL + 'latest.json', function (err, txt) {
      var L = null;
      if (!err) { try { L = JSON.parse(txt); } catch (e) { err = 'bad file'; } }
      if (err || !L || !L.version) { st.busy = false; st.status = 'error'; st.error = err || 'bad file'; cb({ status: 'error' }); return; }
      st.latest = L;
      st.checkedAt = now();
      var have = ready() || BOOT.running;
      if (cmp(L.version, have) <= 0 || L.version === ls('ota.bad')) {
        st.busy = false;
        st.status = ready() ? 'ready' : 'latest';
        cb({ status: st.status, version: ready() || BOOT.running, notes: readyNotes() });
        return;
      }
      if ((L.minShell || 1) > BOOT.shell) {
        st.busy = false; st.status = 'needShell';
        cb({ status: 'needShell', version: L.version, notes: L.notes || [] });
        return;
      }
      get(BASE_URL + L.bundle, function (err2, txt2) {
        st.busy = false;
        var B = null;
        if (!err2) { try { B = JSON.parse(txt2); } catch (e) { err2 = 'bad file'; } }
        var ok = B && B.version === L.version && B.html && B.css !== undefined && B.js && B.js.length;
        if (ok) {
          var all = B.html + B.css;
          for (var i = 0; i < B.js.length; i++) all += B.js[i].code;
          ok = sum(all) === L.sum;
        }
        if (err2 || !ok) { st.status = 'error'; st.error = err2 || 'damaged download'; cb({ status: 'error' }); return; }
        try {
          localStorage.setItem('ota.bundle', txt2);
        } catch (e) {
          st.status = 'error'; st.error = 'no space'; cb({ status: 'error' }); return;
        }
        ls('ota.ready', B.version);
        ls('ota.readyNotes', JSON.stringify(B.notes || []));
        st.status = 'ready';
        cb({ status: 'ready', version: B.version, notes: B.notes || [], fresh: true });
      });
    });
  }

  function readyNotes() {
    try { return JSON.parse(ls('ota.readyNotes') || '[]'); } catch (e) { return []; }
  }

  function autoCheck() {
    if (!auto()) return;
    check(function (r) {
      if (r.status === 'ready' && r.fresh && window.UI) {
        UI.toast('تحديث جديد (' + r.version + ') جاهز — هيشتغل لما تفتح التطبيق المرة الجاية', 6000);
      }
    });
  }

  /* called as soon as the app has started: this version works */
  function start() {
    ls('ota.trying', null);
    setTimeout(autoCheck, FIRST_CHECK);
    setInterval(autoCheck, EVERY);
  }

  function restart() {
    try { if (window.Player && Player.stop) Player.stop(); } catch (e) {}
    location.reload();
  }

  /* forget every downloaded version: the code inside the package runs again */
  function reset() {
    /* and do not download this same version again (a newer one is fine) */
    var v = BOOT.from === 'update' ? BOOT.running : ls('ota.ready');
    if (v) ls('ota.bad', v);
    ls('ota.bundle', null); ls('ota.ready', null); ls('ota.readyNotes', null); ls('ota.trying', null);
    restart();
  }

  /* ---------------- the "updates" item in the settings ---------------- */
  function summary() {
    var v = 'الإصدار ' + BOOT.running;
    if (ready()) return v + ' · تحديث ' + ready() + ' جاهز';
    if (st.status === 'needShell') return v + ' · تحديث كبير متاح';
    return v;
  }
  function hint() {
    if (!auto()) return 'التحديث التلقائي متوقف — اضغط للبحث عن تحديث';
    return 'بيدوّر على تحديثات لوحده كل 6 ساعات وينزّلها';
  }
  function notesText(n) { return n && n.length ? '• ' + n.join('\n• ') : ''; }

  function offerRestart(v, notes, onDone) {
    UI.confirm({
      title: 'التحديث ' + v + ' جاهز', text: notesText(notes) || 'هيشتغل بعد إعادة تشغيل التطبيق.',
      buttons: [{ label: 'إعادة تشغيل التطبيق الآن', value: 'now' }, { label: 'بعدين', value: 'later' }],
      onSelect: function (x) { if (x === 'now') restart(); else if (onDone) onDone(); }
    });
  }

  function checkNow(onDone) {
    UI.loading(true, 'بيدوّر على تحديث...');
    check(function (r) {
      UI.loading(false);
      if (r.status === 'ready') { offerRestart(r.version, r.notes, onDone); return; }
      if (r.status === 'latest') UI.toast('عندك آخر إصدار (' + BOOT.running + ')');
      else if (r.status === 'needShell') {
        UI.confirm({
          title: 'تحديث كبير متاح (' + r.version + ')',
          text: 'التحديث ده محتاج يتسطّب من اللابتوب مرة واحدة، وبعدها التحديثات ترجع تنزل لوحدها.',
          buttons: [{ label: 'تمام', value: 'ok' }], onSelect: function () { if (onDone) onDone(); }
        });
        return;
      }
      else if (r.status === 'busy') UI.toast('بيدوّر على تحديث بالفعل...');
      else UI.toast('مش قادر يوصل لسيرفر التحديثات — اتأكد من الإنترنت');
      if (onDone) onDone();
    });
  }

  function menu(onDone) {
    var items = [];
    if (ready()) items.push({ label: 'تشغيل التحديث ' + ready() + ' الآن', value: 'apply' });
    items.push({ label: 'البحث عن تحديث الآن', value: 'check' });
    items.push({ label: 'التحديث التلقائي: ' + (auto() ? 'مفعّل' : 'متوقف'), value: 'auto',
      sub: auto() ? 'اضغط للإيقاف' : 'اضغط للتفعيل' });
    if (BOOT.notes && BOOT.notes.length) items.push({ label: 'إيه الجديد في الإصدار ' + BOOT.running, value: 'notes' });
    if (BOOT.from === 'update') items.push({ label: 'الرجوع للنسخة الأصلية (' + BOOT.base + ')', value: 'reset',
      sub: 'لو التحديث فيه مشكلة' });
    UI.menu({
      title: 'التحديثات · الإصدار ' + BOOT.running, items: items,
      onSelect: function (v) {
        if (v === 'apply') restart();
        else if (v === 'check') checkNow(onDone);
        else if (v === 'auto') { setAuto(!auto()); UI.toast(auto() ? 'التحديث التلقائي مفعّل' : 'التحديث التلقائي متوقف'); if (onDone) onDone(); }
        else if (v === 'notes') {
          UI.confirm({ title: 'الجديد في الإصدار ' + BOOT.running, text: notesText(BOOT.notes),
            buttons: [{ label: 'تمام', value: 'ok' }], onSelect: function () { if (onDone) onDone(); } });
        }
        else if (v === 'reset') {
          UI.confirm({
            title: 'الرجوع للنسخة الأصلية؟', text: 'هيتشال التحديث ' + BOOT.running + ' ويرجع الإصدار ' + BOOT.base + '. بياناتك ومفضلتك مش هتتأثر.',
            buttons: [{ label: 'رجوع', value: 'yes', danger: true }, { label: 'إلغاء', value: 'no' }], index: 1,
            onSelect: function (x) { if (x === 'yes') reset(); else if (onDone) onDone(); }
          });
        }
        else if (onDone) onDone();
      }
    });
  }

  return {
    start: start, check: check, menu: menu, summary: summary, hint: hint,
    running: function () { return BOOT.running; }, from: function () { return BOOT.from; },
    status: function () { return st; }, ready: ready, auto: auto
