    custom: '<svg viewBox="0 0 24 24"><path d="M3 17v4h4l11-11-4-4L3 17zm17.7-10.3a1 1 0 000-1.4l-2.3-2.3a1 1 0 00-1.4 0l-1.8 1.8 4 4 1.5-2.1z"/></svg>'
  };

  var S = load();
