    try { tizen.application.launch(a.id, function () {}, fail); } catch (e) { fail(e); }
  }

  /* one app button: the TV's own picture of the app, a coloured letter if there is none */
  function hue(s) { var h = 0; for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360; return h; }
  function frame(a) {
    var hh = hue(a.name), letter = a.name.charAt(0).toUpperCase();
    return '<div class="frame"><div class="ph" style="background:linear-gradient(135deg,hsl(' + hh + ',55%,40%),hsl(' + ((hh + 40) % 360) + ',60%,22%))">' +
      esc(letter) + '</div>' + (a.icon ? '<img src="' + esc(a.icon) + '" alt="">' : '') + '</div>';
  }
  function hideBroken(root) {
    var im = root.getElementsByTagName('img');
    for (var i = 0; i < im.length; i++) im[i].addEventListener('error', function () { this.style.display = 'none'; });
  }

  /* ---------------- the row of buttons ---------------- */
  function rowItems() {
    var r = [];
    for (var i = 0; S.favs && i < S.favs.length; i++) if (byId[S.favs[i]]) r.push({ kind: 'app', app: byId[S.favs[i]] });
    r.push({ kind: 'all' });
    r.push({ kind: 'custom' });
    return r;
  }
  function favCount() { var n = 0, r = rowItems(); for (var i = 0; i < r.length; i++) if (r[i].kind === 'app') n++; return n; }

  function renderRow() {
    var r = rowItems(), h = '';
    if (rowIdx >= r.length) rowIdx = r.length - 1;
    for (var i = 0; i < r.length; i++) {
      var it = r[i], cls = 'tile' + (i === rowIdx && zone === 'row' ? ' focus' : '') + (i === rowIdx && moving ? ' moving' : '');
      if (it.kind === 'app') {
        h += '<div class="' + cls + '"><span class="arr r">›</span><span class="arr l">‹</span>' + frame(it.app) + '<div class="name">' + esc(it.app.name) + '</div></div>';
      } else {
        h += '<div class="' + cls + '"><div class="frame"><div class="glyph">' + GLYPH[it.kind] + '</div></div><div class="name">' +
          (it.kind === 'all' ? 'كل التطبيقات' : 'تخصيص الواجهة') + '</div></div>';
      }
    }
    $('row').innerHTML = h;
    hideBroken($('row'));
    scrollRow();
  }
  function paintRow() {
    var t = $('row').children;
    for (var i = 0; i < t.length; i++) {
      var c = t[i].className.replace(/ ?(focus|moving)/g, '');
      if (i === rowIdx && zone === 'row') c += ' focus' + (moving ? ' moving' : '');
      t[i].className = c;
    }
    scrollRow();
  }
  /* keep the chosen button on screen (the row starts on the right) */
  function scrollRow() {
    var step = STEP[S.size], tw = TW[S.size], view = 1920 - 160;
    var x = rowIdx * step, n = $('row').children.length;
    var max = Math.max(0, n * step - (step - tw) - view);
    if (x + tw + 40 > rowOff + view) rowOff = x + tw + 40 - view;
    if (x - 40 < rowOff) rowOff = Math.max(0, x - 40);
    rowOff = Math.min(rowOff, max);
    var t = 'translateX(' + rowOff + 'px)';
    $('row').style.webkitTransform = t;
    $('row').style.transform = t;
  }

  function rowKey(k) {
    var r = rowItems(), it = r[rowIdx];
    if (moving) {
      var nf = favCount();
      if (k === 'left' || k === 'right') {
        var to = rowIdx + (k === 'left' ? 1 : -1);
        if (to < 0 || to >= nf) return;
        var ids = [];
        for (var i = 0; i < r.length; i++) if (r[i].kind === 'app') ids.push(r[i].app.id);
        var tmp = ids[rowIdx]; ids[rowIdx] = ids[to]; ids[to] = tmp;
        /* keep apps that are not on this TV right now where they were */
        var rest = [];
        for (var j = 0; j < S.favs.length; j++) if (!byId[S.favs[j]]) rest.push(S.favs[j]);
        S.favs = ids.concat(rest);
        rowIdx = to;
        renderRow();
      } else if (k === 'enter' || k === 'back' || k === 'hold') {
        moving = false;
        save();
        paintRow();
        UI.toast('تم حفظ الترتيب');
      }
      return;
    }
    if (k === 'left') { if (rowIdx < r.length - 1) { rowIdx++; paintRow(); } }
    else if (k === 'right') { if (rowIdx > 0) { rowIdx--; paintRow(); } }
    else if (k === 'enter') {
      if (it.kind === 'app') launch(it.app);
      else if (it.kind === 'all') openDrawer();
      else customize(0);
    }
    else if (k === 'hold') {
      if (it.kind === 'app') tileMenu(it.app);
      else if (it.kind === 'custom') customize(0);
      else openDrawer();
    }
    else if (k === 'red') customize(0);
    else if (k === 'green') openDrawer();
    else if (k === 'back') exitConfirm();
  }

  function tileMenu(a) {
    UI.menu({
      title: a.name,
      items: [
        { label: 'فتح', value: 'open' },
        { label: 'نقل الزر', sub: 'حرّكه بالأسهم يمينًا أو يسارًا ثم اضغط OK', value: 'move' },
        { label: 'إزالة من الواجهة', sub: 'سيبقى التطبيق على التلفزيون', value: 'remove', danger: true }
      ],
      onSelect: function (v) {
        if (v === 'open') launch(a);
        else if (v === 'move') startMove();
        else if (v === 'remove') {
          S.favs.splice(S.favs.indexOf(a.id), 1);
          save();
          renderRow();
          UI.toast('تمت إزالة ' + a.name + ' من الواجهة');
        }
      }
    });
  }
  function startMove() {
    if (!favCount()) { UI.toast('لا توجد أزرار لترتيبها، أضف تطبيقات أولًا'); return; }
    if (rowItems()[rowIdx].kind !== 'app') rowIdx = 0;
    moving = true;
    zone = 'row';
    paintRow();
    UI.toast('حرّك الزر بالأسهم ثم اضغط OK', 4000);
  }

  function exitConfirm() {
    UI.confirm({
      title: 'الخروج من الواجهة؟',
      buttons: [{ label: 'خروج', value: 'exit', danger: true }, { label: 'إلغاء', value: 'no' }], index: 1,
      onSelect: function (v) {
        if (v !== 'exit') return;
        try { tizen.application.getCurrentApplication().exit(); } catch (e) { UI.toast('الخروج متاح على التلفزيون فقط'); }
      }
    });
  }

  /* ---------------- all the TV's apps ---------------- */
  function openDrawer() {
    zone = 'drawer';
    gridIdx = 0; gridOff = 0;
    $('drawer').className = 'drawer open';
    $('app').className = 'in-drawer';
    renderGrid();
    paintRow();
  }
  function closeDrawer() {
    zone = 'row';
    $('drawer').className = 'drawer';
    $('app').className = '';
    renderRow();
  }
  function renderGrid() {
    $('dcount').innerHTML = apps.length ? '(' + apps.length + ')' : '';
    if (!apps.length) { $('grid').innerHTML = '<div class="dempty">لم يتم العثور على تطبيقات على هذا التلفزيون.</div>'; return; }
    if (gridIdx >= apps.length) gridIdx = apps.length - 1;
    var h = '';
    for (var i = 0; i < apps.length; i++) {
      h += '<div class="app' + (isFav(apps[i].id) ? ' fav' : '') + (i === gridIdx ? ' focus' : '') + '"><span class="badge">★</span>' + frame(apps[i]) +
        '<div class="name">' + esc(apps[i].name) + '</div></div>';
    }
    $('grid').innerHTML = h;
    hideBroken($('grid'));
    scrollGrid();
  }
  function paintGrid() {
    var t = $('grid').children;
    for (var i = 0; i < t.length; i++) {
      var c = t[i].className.replace(/ ?(focus|fav)/g, '');
      if (apps[i] && isFav(apps[i].id)) c += ' fav';
      if (i === gridIdx) c += ' focus';
      t[i].className = c;
    }
    scrollGrid();
  }
  function scrollGrid() {
    var rowH = 262, view = $('gridview').clientHeight || 820, line = Math.floor(gridIdx / COLS);
    var y = 34 + line * rowH;
    if (y + rowH + 30 > gridOff + view) gridOff = y + rowH + 30 - view;
    if (y - 34 < gridOff) gridOff = Math.max(0, y - 34);
    var t = 'translateY(' + (-gridOff) + 'px)';
    $('grid').style.webkitTransform = t;
    $('grid').style.transform = t;
  }
  function gridKey(k) {
    var n = apps.length, a = apps[gridIdx];
    if (k === 'back' || k === 'green') { closeDrawer(); return; }
    if (!n) return;
    if (k === 'left') { if (gridIdx < n - 1 && (gridIdx + 1) % COLS) { gridIdx++; paintGrid(); } }
    else if (k === 'right') { if (gridIdx % COLS) { gridIdx--; paintGrid(); } }
    else if (k === 'down') { if (gridIdx + COLS < n) gridIdx += COLS; else if (Math.floor(gridIdx / COLS) < Math.floor((n - 1) / COLS)) gridIdx = n - 1; paintGrid(); }
    else if (k === 'up') { if (gridIdx - COLS >= 0) { gridIdx -= COLS; paintGrid(); } }
    else if (k === 'enter') { closeDrawer(); launch(a); }
    else if (k === 'hold') {
      if (!S.favs) S.favs = [];
      if (isFav(a.id)) { S.favs.splice(S.favs.indexOf(a.id), 1); UI.toast('تمت إزالة ' + a.name + ' من الواجهة'); }
      else { S.favs.push(a.id); UI.toast('تمت إضافة ' + a.name + ' للواجهة'); }
      save();
      paintGrid();
    }
  }

  /* ---------------- "customise the home screen" ---------------- */
  function cycle(list, v, dir) { var i = list.indexOf(v); return list[(i + dir + list.length) % list.length]; }
  function customize(index) {
    zone = 'row';
    var items = [
      { value: 'bg', label: 'الخلفية', val: BG[S.bg], side: true },
      { value: 'size', label: 'حجم الأزرار', val: SIZE[S.size], side: true },
      { value: 'wx', label: 'الطقس', val: S.wx ? 'ظاهر' : 'مخفي', side: true },
      { value: 'news', label: 'شريط أخبار الرياضة', val: S.news ? 'ظاهر' : 'مخفي', side: true },
      { value: 'add', label: 'إضافة تطبيقات للواجهة', sub: 'من قائمة كل التطبيقات (OK مطوّل على التطبيق)' },
      { value: 'move', label: 'ترتيب الأزرار', sub: 'نقل زر إلى مكان آخر في الصف' }
    ];
    if (window.OTA) items.push({ value: 'updates', label: 'التحديثات', sub: OTA.summary() });
    items.push({ value: 'reset', label: 'الرجوع للواجهة الأصلية', danger: true });
    UI.menu({
      title: 'تخصيص الواجهة', items: items, index: index,
      onSide: function (it, dir, i) {
        if (it.value === 'bg') S.bg = cycle(BGS, S.bg, dir);
        else if (it.value === 'size') { S.size = cycle(SIZES, S.size, dir); rowOff = 0; }
        else if (it.value === 'wx') { S.wx = !S.wx; if (S.wx) weather(); }
        else if (it.value === 'news') { S.news = !S.news; if (S.news) news(); else stopTicker(); }
        save();
        applyLook();
        renderRow();
        if (S.news) startTicker();
        customize(i);
      },
      onSelect: function (v) {
        if (v === 'add') openDrawer();
        else if (v === 'move') startMove();
        else if (v === 'updates') OTA.menu(function () { customize(6); });
        else if (v === 'reset') {
          UI.confirm({
            title: 'الرجوع للواجهة الأصلية؟', text: 'ستعود الأزرار والخلفية والإعدادات كما كانت أول مرة.',
            buttons: [{ label: 'رجوع', value: 'yes', danger: true }, { label: 'إلغاء', value: 'no' }], index: 1,
            onSelect: function (x) {
              if (x !== 'yes') { customize(items.length - 1); return; }
              S = defaults();
              S.favs = firstFavs();
              save();
              applyLook();
              rowIdx = 0; rowOff = 0;
              renderRow();
              if (S.news) news();
              weather();
              UI.toast('رجعت الواجهة كما كانت');
            }
          });
        }
      }
    });
  }

  /* ---------------- clock and dates ---------------- */
  function tick() {
    var d = SaudiTime.now();
    var min = d.getUTCHours() * 60 + d.getUTCMinutes();
    if (min === lastMin) return;
    lastMin = min;
    var p = SaudiTime.parts12(d);
    $('clock').innerHTML = p.time;
    $('ampm').innerHTML = p.ampm;
    $('date').innerHTML = esc(SaudiTime.gregorian(d));
    $('hijri').innerHTML = esc(SaudiTime.hijriText(d));
  }

  function get(url, cb) {
    try {
      var x = new XMLHttpRequest();
      x.open('GET', url);
      x.timeout = 20000;
      x.onload = function () { cb(x.status, x.responseText); };
      x.onerror = x.ontimeout = function () { cb(0, ''); };
      x.send();
    } catch (e) { cb(0, ''); }
  }

  /* ---------------- weather (Riyadh, Open-Meteo) ---------------- */
  var WX = {
    sun: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="5" fill="#ffc83d"/><g stroke="#ffc83d" stroke-width="2" stroke-linecap="round"><path d="M12 1.5v2.5M12 20v2.5M1.5 12H4M20 12h2.5M4.6 4.6l1.8 1.8M17.6 17.6l1.8 1.8M4.6 19.4l1.8-1.8M17.6 6.4l1.8-1.8"/></g></svg>',
    moon: '<svg viewBox="0 0 24 24"><path d="M15.5 3a9 9 0 105.5 14.6A8 8 0 0115.5 3z" fill="#ffe08a"/></svg>',
    part: '<svg viewBox="0 0 24 24"><circle cx="9" cy="9" r="4.2" fill="#ffc83d"/><path d="M8 20h10a4 4 0 00.4-8 5.5 5.5 0 00-10.4 1.6A3.2 3.2 0 008 20z" fill="#e8edf5"/></svg>',
    cloud: '<svg viewBox="0 0 24 24"><path d="M6.5 19h11a4.5 4.5 0 00.5-9 6 6 0 00-11.4 1.8A3.6 3.6 0 006.5 19z" fill="#d7deea"/></svg>',
    rain: '<svg viewBox="0 0 24 24"><path d="M6.5 15h11a4.5 4.5 0 00.5-9 6 6 0 00-11.4 1.8A3.6 3.6 0 006.5 15z" fill="#d7deea"/><g stroke="#5ab0ff" stroke-width="2" stroke-linecap="round"><path d="M8 18l-1 3M12 18l-1 3M16 18l-1 3"/></g></svg>',
    storm: '<svg viewBox="0 0 24 24"><path d="M6.5 14h11a4.5 4.5 0 00.5-9 6 6 0 00-11.4 1.8A3.6 3.6 0 006.5 14z" fill="#c5ccd8"/><path d="M12.5 13l-3 5h3l-1.5 4.5 4.5-6.5h-3l1.5-3z" fill="#ffc83d"/></svg>',
    fog: '<svg viewBox="0 0 24 24"><g stroke="#d7deea" stroke-width="2.2" stroke-linecap="round"><path d="M3 8h18M5 12h14M3 16h18M7 20h10"/></g></svg>'
  };
  function wxInfo(code, day) {
    if (code === 0) return { t: 'صافٍ', i: day ? 'sun' : 'moon' };
    if (code === 1 || code === 2) return { t: 'غائم جزئيًا', i: day ? 'part' : 'cloud' };
    if (code === 3) return { t: 'غائم', i: 'cloud' };
    if (code === 45 || code === 48) return { t: 'ضباب', i: 'fog' };
    if (code >= 51 && code <= 57) return { t: 'رذاذ', i: 'rain' };
    if (code >= 61 && code <= 67) return { t: 'ممطر', i: 'rain' };
    if (code >= 71 && code <= 77) return { t: 'ثلوج', i: 'cloud' };
    if (code >= 80 && code <= 82) return { t: 'زخات مطر', i: 'rain' };
    if (code >= 95) return { t: 'عواصف رعدية', i: 'storm' };
    return { t: '', i: day ? 'sun' : 'moon' };
  }
  function showWeather(c) {
    if (!c || typeof c.temperature_2m !== 'number') return;
    var w = wxInfo(c.weather_code, c.is_day !== 0);
    $('wx').innerHTML = WX[w.i] + '<b dir="ltr">' + Math.round(c.temperature_2m) + '°</b><span>' + esc(w.t ? w.t + ' · الرياض' : 'الرياض') + '</span>';
  }
  function weather() {
    if (!S.wx) return;
    wxAt = now();
    if (window.__demoWeather) { showWeather(window.__demoWeather); return; }
    get('https://api.open-meteo.com/v1/forecast?latitude=24.71&longitude=46.68&current=temperature_2m,weather_code,is_day&timezone=Asia%2FRiyadh',
      function (status, body) { if (status === 200) try { showWeather(JSON.parse(body).current); } catch (e) {} });
  }

  /* ---------------- sports news ticker (Google News, sport, Arabic) ---------------- */
  function parseNews(xml) {
    var out = [];
    try {
      var doc = new DOMParser().parseFromString(xml, 'text/xml');
      var items = doc.getElementsByTagName('item');
      for (var i = 0; i < items.length && out.length < 20; i++) {
        var t = items[i].getElementsByTagName('title')[0];
        var s = items[i].getElementsByTagName('source')[0];
        if (!t) continue;
        var title = t.textContent.replace(/\s+/g, ' ').trim(), src = s ? s.textContent.trim() : '';
        var cut = title.lastIndexOf(' - ');
        if (cut > 20) { if (!src) src = title.slice(cut + 3); title = title.slice(0, cut); }
        if (title) out.push({ t: title, s: src });
      }
    } catch (e) {}
    return out;
  }
  function stopTicker() { if (tickerAnim) { try { tickerAnim.cancel(); } catch (e) {} tickerAnim = null; } }
  function startTicker() {
    var track = $('ttrack'), view = $('tview');
    stopTicker();
    if (!newsItems.length || !S.news) return;
    var h = '';
    for (var i = 0; i < newsItems.length; i++) {
      h += '<span class="it">' + esc(newsItems[i].t) + '</span>' + (newsItems[i].s ? '<span class="src">' + esc(newsItems[i].s) + '</span>' : '') + '<span class="dot"></span>';
    }
    track.innerHTML = h;
    $('tmsg').style.display = 'none';
    /* Arabic: moves from left to right, the first headline comes in first */
    var tw = track.scrollWidth, vw = view.clientWidth, speed = 90;
    if (track.animate && tw && vw) {
      tickerAnim = track.animate([{ transform: 'translateX(' + (-tw) + 'px)' }, { transform: 'translateX(' + vw + 'px)' }],
        { duration: Math.round((tw + vw) / speed * 1000), iterations: Infinity });
      if (window.__demoTickerAt) tickerAnim.currentTime = window.__demoTickerAt * tickerAnim.effect.getTiming().duration;
    }
  }
  function news() {
    if (!S.news) return;
    newsAt = now();
    if (window.__demoNews) { newsItems = window.__demoNews; startTicker(); return; }
    get(NEWS, function (status, body) {
      var items = status === 200 ? parseNews(body) : [];
      if (items.length) { newsItems = items; startTicker(); }
      else if (!newsItems.length) { $('tmsg').innerHTML = 'تعذّر تحميل الأخبار، ستتم المحاولة مرة أخرى'; setTimeout(news, 120000); }
    });
  }

  /* ---------------- remote control ---------------- */
  var NAMES = { 37: 'left', 38: 'up', 39: 'right', 40: 'down', 13: 'enter', 10009: 'back', 27: 'back', 8: 'back',
    403: 'red', 404: 'green', 405: 'yellow', 406: 'blue', 10182: 'exit' };
  /* holding OK (650 ms) = 'hold'; a short press = 'enter' when OK is let go */
  var HOLD_MS = 650, hold = null, keyupSeen = false;
  function wantsHold() { return !UI.modal() && ((zone === 'row' && !moving) || zone === 'drawer'); }
  function dispatch(k) {
    var m = UI.modal();
    if (m) { m.onKey(k); return; }
    if (zone === 'drawer') gridKey(k); else rowKey(k);
  }
  function fireHold() {
    if (!hold || hold.done) return;
    hold.done = true;
    clearTimeout(hold.timer);
    dispatch('hold');
  }
  function onKeyDown(e) {
    var k = NAMES[e.keyCode];
    if (!k) return;
    e.preventDefault();
    if (k === 'exit') { try { tizen.application.getCurrentApplication().exit(); } catch (x) {} return; }
    if (k === 'enter' && (hold || wantsHold())) {
      if (hold) { if (now() - hold.t0 >= HOLD_MS) fireHold(); return; }
      if (e.repeat) return;
      hold = { t0: now(), done: false };
      hold.timer = setTimeout(function () {
        if (!hold || hold.done) return;
        if (keyupSeen) { fireHold(); return; }
        hold = null;                     /* this TV sends no key-up: a normal press */
        dispatch('enter');
      }, HOLD_MS);
      return;
    }
    dispatch(k);
  }
  function onKeyUp(e) {
    keyupSeen = true;
    if (e.keyCode !== 13 || !hold) return;
    var h = hold;
    hold = null;
    clearTimeout(h.timer);
    if (!h.done) dispatch('enter');
  }

  /* ---------------- start ---------------- */
  function fit() {
    var w = window.innerWidth, h = window.innerHeight;
    if (!w || !h) return;
    var s = Math.min(w / 1920, h / 1080);
    var t = Math.abs(s - 1) > 0.01 ? 'translate(' + Math.round((w - 1920 * s) / 2) + 'px,' + Math.round((h - 1080 * s) / 2) + 'px) scale(' + s + ')' : '';
    $('app').style.webkitTransform = t;
    $('app').style.transform = t;
  }

  function onShow() {
    if (document.hidden) return;
    /* back from another app: a downloaded update starts now */
    if (window.OTA && OTA.ready() && !UI.modal() && !moving) { location.reload(); return; }
    lastMin = -1;
    tick();
    loadApps();
    if (now() - wxAt > 30 * 60000) weather();
    if (now() - newsAt > 20 * 60000) news();
  }

  function init() {
    applyLook();
    fit();
    window.addEventListener('resize', fit);
    try {
      tizen.tvinputdevice.registerKeyBatch(['ColorF0Red', 'ColorF1Green', 'ColorF2Yellow', 'ColorF3Blue']);
    } catch (e) {
      try { tizen.tvinputdevice.registerKey('ColorF0Red'); tizen.tvinputdevice.registerKey('ColorF1Green'); } catch (e2) {}
    }
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('keyup', onKeyUp);
    document.addEventListener('visibilitychange', onShow);
    renderRow();
    loadApps();
    tick();
    setInterval(tick, 1000);
    weather();
    setInterval(weather, 30 * 60000);
    news();
    setInterval(news, 20 * 60000);
    if (window.OTA) OTA.start();
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();

  return { key: dispatch, state: function () { return { zone: zone, rowIdx: rowIdx, moving: moving, gridIdx: gridIdx, S: S, apps: apps.length }; } };
})();
